Here is a clean asynchronous Python implementation:

```python
import asyncio
import psutil
from typing import Dict, Any

async def get_system_telemetry() -> Dict[str, Any]:
    try:
        cpu = psutil.cpu_percent(interval=None)
        mem = psutil.virtual_memory()
        return {
            "status": "success",
            "cpu_percent": cpu,
            "memory_percent": mem.percent,
            "memory_used_gb": round(mem.used / (1024 ** 3), 2)
        }
    except Exception as e:
        return {"status": "error", "detail": str(e)}

if __name__ == '__main__':
    print(asyncio.run(get_system_telemetry()))
```

Here is a modern, responsive React + TypeScript component:

```tsx
import React, { useState } from 'react';

interface MetricCardProps {
  title: string;
  value: string | number;
  unit?: string;
  badgeColor?: string;
}

export const MetricCard: React.FC<MetricCardProps> = ({
  title,
  value,
  unit = '',
  badgeColor = '#f43f5e'
}) => {
  const [hovered, setHovered] = useState(false);

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        padding: '16px 20px',
        borderRadius: '12px',
        background: 'rgba(255, 255, 255, 0.04)',
        border: `1px solid ${hovered ? badgeColor : 'rgba(255, 255, 255, 0.08)'}`,
        transition: 'all 0.2s ease'
      }}
    >
      <div style={{ fontSize: '12px', color: '#94a3b8', marginBottom: '4px' }}>{title}</div>
      <div style={{ fontSize: '22px', fontWeight: 700, color: '#ffffff' }}>
        {value} <span style={{ fontSize: '14px', color: badgeColor }}>{unit}</span>
      </div>
    </div>
  );
};
```

